"""``phzyx add auth`` — scaffold phzyx-auth into an existing FastAPI app tree."""

from __future__ import annotations

from pathlib import Path

AUTH_MODULE = '''\
"""Auth wiring generated by ``phzyx add auth``.

Install: ``uv add phzyx-auth[fastapi]``
Env: ``PHZYX_AUTH_SECRET`` (≥32 bytes), optional ``PHZYX_AUTH_PRODUCTION=1``.
"""

from __future__ import annotations

import os
from collections.abc import Callable

from phzyx.auth import (
    AUTH_MODELS,
    AuthConfig,
    AuthService,
    HybridUserMap,
    OrmAPIKeyStore,
    OrmPasswordResetStore,
    OrmSessionStore,
    OrmUserRepository,
    PhzyxAuthz,
)
from phzyx.auth.adapters.fastapi import mount_auth
from phzyx.orm.session_sync import Session
from phzyx.schema.types import Dialect

SessionFactory = Callable[[], Session]


def build_auth_service(
    session_factory: SessionFactory,
    *,
    dialect: Dialect = Dialect.SQLITE,
) -> AuthService:
    """ORM-backed AuthService (sessions, users, API keys, password reset)."""
    secret = os.environ.get("PHZYX_AUTH_SECRET", "")
    if not secret:
        secret = "dev-only-insecure-secret-min-32b!!"
    production = os.environ.get("PHZYX_AUTH_PRODUCTION", "").lower() in {
        "1",
        "true",
        "yes",
    }
    cfg = AuthConfig(
        secret=secret,
        production=production,
        cookie_secure=production,
        csrf_protect=True,
    )
    repo = OrmUserRepository(session_factory=session_factory)
    return AuthService(
        config=cfg,
        sessions=OrmSessionStore(session_factory=session_factory),
        api_keys=OrmAPIKeyStore(session_factory=session_factory),
        password_reset_store=OrmPasswordResetStore(session_factory=session_factory),
        users=HybridUserMap(repo=repo),  # type: ignore[arg-type]
    )


def install_auth(app, session_factory: SessionFactory, *, prefix: str = "/auth") -> AuthService:
    """Mount routes + return service. Push AUTH_MODELS with your schema push."""
    svc = build_auth_service(session_factory)
    mount_auth(app, svc, prefix=prefix, middleware=True)
    app.state.phzyx_auth = svc
    return svc


def authz_for_admin(*, require_staff: bool = True) -> PhzyxAuthz:
    return PhzyxAuthz(require_staff=require_staff)


# Re-export models so ``phzyx db push --models yourapp.auth:AUTH_MODELS`` works.
__all__ = [
    "AUTH_MODELS",
    "authz_for_admin",
    "build_auth_service",
    "install_auth",
]
'''

README_SNIPPET = """\
# Auth (phzyx-auth)

Generated by `phzyx add auth`.

## Setup

```bash
uv add "phzyx-auth[fastapi]"
export PHZYX_AUTH_SECRET="$(python -c 'import secrets; print(secrets.token_urlsafe(32))')"
```

Push auth tables with your models:

```bash
phzyx db push --models path.to.auth:AUTH_MODELS --yes
phzyx auth create-superuser --email you@yourdomain.com --password 'use-a-long-unique-secret'
```

## FastAPI

```python
from fastapi import FastAPI
from yourapp.auth import AUTH_MODELS, authz_for_admin, install_auth

app = FastAPI()
# session_factory: () -> phzyx.orm.Session
auth = install_auth(app, session_factory)

# AdminBoard
# AdminBoard(app, models=[...], session_factory=session_factory, authz=authz_for_admin())
```

SPA cookie login: `POST /auth/login` → set cookies + `csrf_token`; send `X-CSRF-Token` on mutations.
"""


def add_auth(
    target: Path,
    *,
    module_name: str = "app/forge/auth.py",
    force: bool = False,
    dry_run: bool = False,
) -> list[Path]:
    """Write auth scaffold under ``target``. Returns written paths."""
    target = target.resolve()
    if not target.is_dir():
        raise FileNotFoundError(f"not a directory: {target}")

    auth_py = target / module_name
    readme = target / "AUTH.md"
    written: list[Path] = []

    content = AUTH_MODULE
    if module_name.replace("\\", "/").endswith("forge/auth.py"):
        from phzyx.cli.scaffold.templates import forge_auth

        content = forge_auth()

    for path, body in ((auth_py, content), (readme, README_SNIPPET)):
        if path.exists() and not force:
            raise FileExistsError(f"refusing to overwrite {path} (use --force)")
        if dry_run:
            written.append(path)
            continue
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(body, encoding="utf-8")
        written.append(path)
    return written
